final class DeliveryService{private $db;private $p;public function __construct(){global $wpdb;$this->db=$wpdb;$this->p=$wpdb->prefix.'ps_';}public static function process_due(){$s=new self();$rows=$s->db->get_results("SELECT * FROM {$s->p}integration_deliveries WHERE status IN ('pending','retry') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP()) ORDER BY id LIMIT 50",ARRAY_A);foreach($rows as $row){if(1===$s->db->update($s->p.'integration_deliveries',array('status'=>'processing'),array('id'=>$row['id'],'status'=>$row['status']))){$s->deliver($row);}}}
	private function deliver($row){$config=$this->db->get_row($this->db->prepare("SELECT * FROM {$this->p}integration_configs WHERE id=%d AND tenant_id=%d AND status='active'",$row['config_id'],$row['tenant_id']),ARRAY_A);$error='';$result=array('success'=>false,'code'=>0,'body'=>'');try{if(!$config){throw new \RuntimeException('Integration configuration is inactive or missing.');}$credentials=array();if($config['encrypted_credentials']){$credentials=(new CredentialVault())->decrypt($config['encrypted_credentials']);if(is_wp_error($credentials)){throw new \RuntimeException($credentials->get_error_message());}}$config['credentials']=$credentials;$adapter=match($config['adapter_key']){'wordpress_email'=>new WordPressEmailAdapter(),'signed_webhook'=>new SignedWebhookAdapter(),default=>throw new \RuntimeException('Configured adapter is not installed.')};$result=$adapter->deliver($config,(array)json_decode($row['payload'],true));if(!$result['success']){$error='Provider returned HTTP '.$result['code'].'.';}}catch(\Throwable $e){$error=$e->getMessage();}$attempt=(int)$row['attempt_count']+1;$success=!empty($result['success']);$status=$success?'delivered':($attempt>=6?'dead_letter':'retry');$next=$success||'dead_letter'===$status?null:gmdate('Y-m-d H:i:s',time()+min(3600,30*(2**$attempt)));$this->db->update($this->p.'integration_deliveries',array('status'=>$status,'attempt_count'=>$attempt,'next_attempt_at'=>$next,'response_code'=>(int)($result['code']??0),'response_body'=>substr((string)($result['body']??''),0,2000),'last_error'=>$error?:null,'updated_at'=>current_time('mysql',true)),array('id'=>$row['id']));do_action('pharmasure_audit_log',array('tenant_id'=>$row['tenant_id'],'action'=>'integration.delivery_'.$status,'object_type'=>'integration_delivery','object_id'=>$row['id'],'details'=>array('config_id'=>$row['config_id'],'event_type'=>$row['event_type'],'attempt'=>$attempt,'response_code'=>$result['code']??0,'error'=>$error)));}
